type TypeKey = 'devis' | 'rdv' | 'client' | 'facture' | 'email' | 'task';
type StatusKey = 'pending' | 'approved' | 'rejected' | 'completed';
type Priority = 'urgent' | 'high' | 'medium' | 'low';
type AgentKey = 'commercial' | 'reception' | 'rh' | 'cfo' | 'marketing' | 'workflow' | 'legal';

interface Action {
  id: string;
  type: TypeKey;
  title: string;
  sub: string;
  agent: AgentKey;
  date: string;
  rawDate: number; // ms epoch for sorting/grouping
  status: StatusKey;
  priority: Priority;
  client?: string;
  value?: number;
  duration?: string;
  unread?: boolean;
  raw: Record<string, unknown>;
}

interface RawWorkItem {
  id: string;
  type: string;
  title?: string;
  summary?: string;
  status?: string;
  agentName?: string;
  agentIcon?: string;
  data?: Record<string, unknown>;
  createdAt?: { _seconds?: number; seconds?: number } | string | number;
}

