const TYPE_FROM_RAW: Record<string, TypeKey> = {
  appointment_created: 'rdv',
  meeting_scheduled: 'rdv',
  client_added: 'client',
  lead_added: 'client',
  quote_created: 'devis',
  invoice_created: 'facture',
  email_sent: 'email',
  email_drafted: 'email',
  newsletter_sent: 'email',
  alert_sent: 'task',
  report_generated: 'task',
  diagnostic_completed: 'task',
  security_check: 'task',
};

function mapType(raw: string): TypeKey {
  return TYPE_FROM_RAW[raw] ?? 'task';
}

function mapAgent(name?: string, fallbackType?: TypeKey): AgentKey {
  const n = (name || '').toLowerCase();
  if (n.includes('commerc')) return 'commercial';
  if (n.includes('récept') || n.includes('recept')) return 'reception';
  if (n.includes('rh') || n.includes('hr')) return 'rh';
  if (n.includes('cfo') || n.includes('compt') || n.includes('finance')) return 'cfo';
  if (n.includes('market')) return 'marketing';
  if (n.includes('legal') || n.includes('lég')) return 'legal';
  if (n.includes('flow')) return 'workflow';
  if (fallbackType === 'devis') return 'commercial';
  if (fallbackType === 'rdv' || fallbackType === 'client') return 'reception';
  if (fallbackType === 'facture') return 'cfo';
  if (fallbackType === 'email') return 'marketing';
  return 'workflow';
}

function mapStatus(s?: string): StatusKey {
  const v = (s || '').toLowerCase();
  if (v === 'approved' || v === 'accepted') return 'approved';
  if (v === 'rejected' || v === 'declined' || v === 'canceled' || v === 'cancelled') return 'rejected';
  if (v === 'completed' || v === 'sent' || v === 'paid' || v === 'done') return 'completed';
  return 'pending';
}

function derivePriority(type: TypeKey, value?: number, ageHours?: number): Priority {
  if (type === 'task' && (ageHours ?? 0) > 72) return 'urgent';
  if (typeof value === 'number') {
    if (value >= 5_000_000) return 'urgent';
    if (value >= 1_000_000) return 'high';
    if (value >= 250_000) return 'medium';
    return 'low';
  }
  return 'medium';
}

function tsToMs(t: RawWorkItem['createdAt']): number {
  if (!t) return Date.now();
  if (typeof t === 'number') return t < 1e12 ? t * 1000 : t;
  if (typeof t === 'string') { const d = Date.parse(t); return isNaN(d) ? Date.now() : d; }
  if (typeof t === 'object') {
    const s = (t as { _seconds?: number; seconds?: number })._seconds ?? (t as { seconds?: number }).seconds;
    return typeof s === 'number' ? s * 1000 : Date.now();
  }
  return Date.now();
}

function formatActionDate(ms: number): string {
  const d = new Date(ms);
  const today = new Date(); today.setHours(0, 0, 0, 0);
  const yest = new Date(today.getTime() - 86_400_000);
  const dayStart = new Date(d); dayStart.setHours(0, 0, 0, 0);
  const hh = String(d.getHours()).padStart(2, '0');
  const mm = String(d.getMinutes()).padStart(2, '0');
  if (dayStart.getTime() === today.getTime()) return `Aujourd'hui · ${hh}:${mm}`;
  if (dayStart.getTime() === yest.getTime()) return `Hier · ${hh}:${mm}`;
  const months = ['janv', 'févr', 'mars', 'avril', 'mai', 'juin', 'juil', 'août', 'sept', 'oct', 'nov', 'déc'];
  return `${d.getDate()} ${months[d.getMonth()]} · ${hh}:${mm}`;
}

function groupKey(ms: number): string {
  const d = new Date(ms);
  const today = new Date(); today.setHours(0, 0, 0, 0);
  const yest = new Date(today.getTime() - 86_400_000);
  const weekStart = new Date(today); weekStart.setDate(today.getDate() - today.getDay());
  const dayStart = new Date(d); dayStart.setHours(0, 0, 0, 0);
  if (dayStart.getTime() === today.getTime()) return "Aujourd'hui";
  if (dayStart.getTime() === yest.getTime()) return 'Hier';
  if (dayStart.getTime() >= weekStart.getTime()) return 'Cette semaine';
  return 'Plus tôt';
}

